{
  "findings": [
    {
      "check_id": "CKV_AZURE_44",
      "title": "Storage account permits outdated TLS and non-HTTPS traffic",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account explicitly permits TLS 1.0 and disables HTTPS-only enforcement, exposing connections to obsolete encryption and unencrypted HTTP traffic."
    },
    {
      "check_id": "CKV2_AZURE_33",
      "title": "Storage account lacks a private endpoint",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account has no private endpoint and does not disable public network access, allowing access through its public service endpoint."
    },
    {
      "check_id": "CKV2_AZURE_38",
      "title": "Blob soft delete is not enabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "Blob versioning is enabled, but no delete retention policy is configured, reducing protection against accidental or malicious deletion."
    },
    {
      "check_id": "CKV2_AZURE_47",
      "title": "Blob anonymous access is not explicitly disabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account does not explicitly disable public access for nested blob items, which could permit anonymous access if a container is configured for it."
    }
  ],
  "patched_code": "variable "media_storage_private_endpoint_subnet_id" {
  description = "Resource ID of the subnet used by the media storage private endpoint."
  type        = string
}

resource "azurerm_storage_account" "media_storage" {
  name                                = "corpmediastorage${random_string.storage_suffix.result}"
  resource_group_name                 = azurerm_resource_group.corporate_media_streaming.name
  location                            = azurerm_resource_group.corporate_media_streaming.location
  account_tier                        = "Standard"
  account_replication_type            = "GRS"
  enable_https_traffic_only           = true
  min_tls_version                     = "TLS1_2"
  public_network_access_enabled       = false
  allow_nested_items_to_be_public     = false

  blob_properties {
    versioning_enabled = true

    delete_retention_policy {
      days = 7
    }
  }
}

resource "azurerm_private_endpoint" "media_storage" {
  name                = "${azurerm_storage_account.media_storage.name}-blob-pe"
  location            = azurerm_resource_group.corporate_media_streaming.location
  resource_group_name = azurerm_resource_group.corporate_media_streaming.name
  subnet_id           = var.media_storage_private_endpoint_subnet_id

  private_service_connection {
    name                           = "${azurerm_storage_account.media_storage.name}-blob-connection"
    private_connection_resource_id = azurerm_storage_account.media_storage.id
    subresource_names              = ["blob"]
    is_manual_connection           = false
  }
}
",
  "fix_summary": "Enforced HTTPS with TLS 1.2, disabled public network and anonymous blob access, and enabled seven-day blob soft delete. Added a blob private endpoint using a caller-supplied subnet ID."
}
